 void Clamp(){double scale=1;using(var g=System.Drawing.Graphics.FromHwnd(IntPtr.Zero))scale=g.DpiX/96.0;var screens=System.Windows.Forms.Screen.AllScreens.Select(s=>new Rect(s.WorkingArea.X/scale,s.WorkingArea.Y/scale,s.WorkingArea.Width/scale,s.WorkingArea.Height/scale)).ToList();var area=screens.FirstOrDefault(a=>a.IntersectsWith(new Rect(Left,Top,Width,Height)));if(area.Width==0)area=SystemParameters.WorkArea;Width=Math.Max(MinWidth,Math.Min(Width,area.Width));Height=Math.Max(MinHeight,Math.Min(Height,area.Height));Left=Math.Max(area.Left,Math.Min(Left,area.Right-Width));Top=Math.Max(area.Top,Math.Min(Top,area.Bottom-Height));}
