 else{var p=DofusCompanion.Find(store.Value,c);var step=DofusCompanion.Current(store.Value,doc);int done=doc.Steps.Count(s=>p!=null&&p.done.Contains(s.Key));body.Children.Add(Text(c.name+(String.IsNullOrEmpty(c.server)?"":" · "+c.server),14));body.Children.Add(Text(doc.Title,11,true));body.Children.Add(Text(done+" / "+doc.Steps.Count+" étapes · "+Math.Round(100.0*done/doc.Steps.Count)+" %",11,true));body.Children.Add(new ProgressBar{Height=4,Maximum=doc.Steps.Count,Value=done,Foreground=Accent,Background=Surface,Margin=new Thickness(0,8,0,16)});body.Children.Add(Text(step.Section,10,true));var title=Text(step.Title,23);title.FontFamily=new FontFamily("Georgia");body.Children.Add(title);body.Children.Add(Text(step.Details==""?"Consultez le guide détaillé pour les instructions de cette quête.":step.Details,12,true));if(step.Resources.Any()){body.Children.Add(Text("RESSOURCES DE LA QUÊTE",10));foreach(var r in step.Resources)body.Children.Add(Text(r.Count+" × "+r.Name,12,true));}var controls=new WrapPanel();controls.Children.Add(Button("←",()=>Move(-1,false)));var finish=Button("Terminé →",()=>Move(1,true),true);finish.IsEnabled=step.CanComplete&&!busy;controls.Children.Add(finish);controls.Children.Add(Button("Suivant",()=>Move(1,false)));footer.Children.Add(controls);var links=new WrapPanel();if(step.CanComplete)links.Children.Add(Button(p!=null&&p.done.Contains(step.Key)?"Annuler ✓":"Valider ✓",()=>Safe(()=>DofusCompanion.Toggle(store,Current()))));links.Children.Add(Button("Guide détaillé",()=>Open(step.Url)));if(!String.IsNullOrEmpty(step.Coordinates))links.Children.Add(Button("Copier /travel",()=>Clipboard.SetText("/travel "+step.Coordinates)));footer.Children.Add(links);}
