 internal static ComboBox Combo(IEnumerable<string> labels,int selected=0){var c=new ComboBox{ItemsSource=labels.ToArray(),SelectedIndex=selected,MinHeight=33};return c;}
 void Configure(){if(testing)return;if(options!=null){options.Activate();return;}Topmost=false;var w=new Window{Title="Compagnon Dofus · Personnages et guides",Width=650,Height=790,MinWidth=500,MinHeight=500,Background=BackgroundColor,Foreground=Ink,FontFamily=FontFamily,Owner=this,WindowStartupLocation=WindowStartupLocation.CenterOwner};w.Resources=Resources;options=w;w.Closed+=delegate{options=null;Topmost=store.Value.dofus.topmost;RefreshView();};BuildOptions(w);w.Show();}
 void BuildOptions(Window w,bool adding=false){var body=new StackPanel{Margin=new Thickness(24)};w.Content=new ScrollViewer{Content=body,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};body.Children.Add(Text("Votre compagnon",26));body.Children.Add(Text("Les données sont propres à cette application. Aucun compte Tougli ni connexion au jeu n’est requis.",12,true));var characters=store.Value.dofus.characters.ToList();var current=adding?null:DofusCompanion.Character(store.Value);var choices=Combo(new[]{"Nouveau personnage…"}.Concat(characters.Select(c=>c.name+" · "+c.server)),current==null?0:characters.FindIndex(c=>c.id==current.id)+1);Field(body,"Personnage actif",choices);var name=new TextBox{Text=current==null?"":current.name,MaxLength=60};var server=new TextBox{Text=current==null?"":current.server,MaxLength=60};var type=Combo(DofusCompanion.ClassNames,current==null?0:Array.IndexOf(DofusCompanion.Classes,current.classCode));string[] ac={"","Neutre","Bonta","Brak"},oc={"","CV","OA","ES","CS","OP","EM"};var alignment=Combo(new[]{"Non renseigné","Neutre","Bontarien","Brâkmarien"},current==null?0:Array.IndexOf(ac,current.alignment));var order=Combo(new[]{"Non renseigné","CV · Cœur Vaillant","OA · Œil Attentif","ES · Esprit Salvateur","CS · Cœur Saignant","OP · Œil Putride","EM · Esprit Malsain"},current==null?0:Array.IndexOf(oc,current.order));Field(body,"Nom",name);Field(body,"Serveur (facultatif)",server);Field(body,"Classe",type);Field(body,"Alignement",alignment);Field(body,"Ordre",order);
 choices.SelectionChanged+=delegate{if(choices.SelectedIndex==0){BuildOptions(w,true);return;}Safe(()=>PersonalWorkflows.Change(store,()=>store.Value.dofus.active=characters[choices.SelectedIndex-1].id));BuildOptions(w);};
 var error=Text("",12);body.Children.Add(Button("Enregistrer le personnage",delegate{try{if(String.IsNullOrWhiteSpace(name.Text))throw new InvalidDataException("Donnez un nom au personnage.");var old=choices.SelectedIndex==0?null:characters[choices.SelectedIndex-1];var updated=new DofusCharacter{id=old==null?Guid.NewGuid().ToString():old.id,name=name.Text.Trim(),server=server.Text.Trim(),classCode=DofusCompanion.Classes[type.SelectedIndex],alignment=ac[alignment.SelectedIndex],order=oc[order.SelectedIndex],guide=old==null?"rsa-rush-sylvestre-accelere":old.guide};PersonalWorkflows.Change(store,()=>{store.Value.dofus.characters.RemoveAll(c=>c.id==updated.id);store.Value.dofus.characters.Add(updated);store.Value.dofus.active=updated.id;});documentKey="";RefreshView();BuildOptions(w);}catch(Exception ex){error.Text=ex.Message;}},true));body.Children.Add(error);
 if(current!=null){var guides=new List<TougliGuideInfo>{new TougliGuideInfo{Slug="rsa-rush-sylvestre-accelere",Title="Rush Sylvestre Accéléré"},new TougliGuideInfo{Slug="dofus-sylvestre",Title="Dofus Sylvestre"}};if(!guides.Any(g=>g.Slug==current.guide))guides.Add(new TougliGuideInfo{Slug=current.guide,Title=current.guide});var guide=Combo(guides.Select(g=>g.Title),guides.FindIndex(g=>g.Slug==current.guide));Field(body,"Parcours Tougli",guide);var guideTools=new WrapPanel();guideTools.Children.Add(Button("Charger / actualiser",()=>RunDownload(async token=>{string slug=guides[guide.SelectedIndex].Slug;var snapshot=new DofusCharacter{id=current.id,classCode=current.classCode,alignment=current.alignment,order=current.order,guide=slug};var raw=await Download("/api/guide/details/"+slug,token);var parsed=TougliReader.Parse(raw,snapshot);if(parsed.Slug!=slug)throw new InvalidDataException("Tougli a renvoyé un autre guide.");token.ThrowIfCancellationRequested();TougliReader.Cache(store,slug,raw);PersonalWorkflows.Change(store,()=>store.Value.dofus.characters.First(c=>c.id==snapshot.id).guide=slug);documentKey="";message="Guide chargé. Votre progression est conservée.";if(options!=null)BuildOptions(options);}),true));guideTools.Children.Add(Button("Tous les guides",()=>RunDownload(async token=>{var catalogue=TougliReader.Catalogue(await Download("/api/guide/list",token));if(catalogue.Count==0)throw new InvalidDataException("Aucun guide trouvé.");guides=catalogue.OrderBy(g=>g.Title).ToList();guide.ItemsSource=guides.Select(g=>g.Title).ToArray();guide.SelectedIndex=Math.Max(0,guides.FindIndex(g=>g.Slug==current.guide));})));body.Children.Add(guideTools);var doc=Current();if(doc!=null){var search=new TextBox{MaxLength=180};Field(body,"Rechercher une étape",search);var list=new ListBox{Height=170,DisplayMemberPath="Display",Background=Surface,Foreground=Ink};Action filter=()=>list.ItemsSource=doc.Steps.Where(s=>(s.Title+" "+s.Section).IndexOf(search.Text,StringComparison.Current