 async void RunDownload(Func<CancellationToken,Task> operation){if(busy)return;busy=true;cancel=new CancellationTokenSource();cancel.CancelAfter(TimeSpan.FromSeconds(50));if(options!=null)options.IsEnabled=false;RefreshView();try{await operation(cancel.Token);}catch(OperationCanceledException){message="Chargement annulé. Progression conservée.";}catch(Exception ex){message="Chargement impossible : "+ex.Message+" Votre dernier guide et votre progression sont conservés.";if(IsLoaded)MessageBox.Show(message,"Tougli");}finally{busy=false;cancel.Dispose();cancel=null;if(options!=null)options.IsEnabled=true;RefreshView();}}
 internal static async Task<string> Download(string endpoint,CancellationToken token){ServicePointManager.SecurityProtocol|=SecurityProtocolType.Tls12;using(var http=new HttpClient(new HttpClientHandler{AllowAutoRedirect=false}){Timeout=TimeSpan.FromSeconds(45)})using(var response=await http.GetAsync(TougliReader.Api+endpoint,HttpCompletionOption.ResponseHeadersRead,token)){response.EnsureSuccessStatusCode();if(response.Content.Headers.ContentLength>TougliReader.MaxBytes)throw new InvalidDataException("Guide trop volumineux.");using(var input=await response.Content.ReadAsStreamAsync())using(var output=new MemoryStream()){var buffer=new byte[16384];int count;while((count=await input.ReadAsync(buffer,0,buffer.Length,token))>0){if(output.Length+count>TougliReader.MaxBytes)throw new InvalidDataException("Guide trop volumineux.");output.Write(buffer,0,count);}return Encoding.UTF8.GetString(output.ToArray());}}}
 internal void Render(string path){var element=(FrameworkElement)Content;element.Width=Width;element.Height=Height;element.Measure(new Size(Width,Height));element.Arrange(new Rect(0,0,Width,Height));element.UpdateLayout();var bitmap=new RenderTargetBitmap((int)Width,(int)Height,96,96,PixelFormats.Pbgra32);bitmap.Render(element);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var f=File.Create(path))encoder.Save(f);}
